// Einmalige Reparatur 2026-09-01 (RatsPilot-Audit-Folgesession, P0.1-Absicherung vom
// 2026-09-01 Folgeauftrag): behebt den 'Legacy-Repair frisst QA-Agent-Ausfaelle'-Bug
// (ALLRIS_P4_Content_Reaktion, Commit 158602f) fuer 5 bereits VOR dem Fix beschaedigte
// historische Zeilen. Kuenftige Faelle sind bereits automatisch geschuetzt.
//
// WICHTIG: dieser Node liefert nur die ZIEL-Liste. Der tatsaechliche Ist-Zustand jeder
// Zeile wird gleich danach im Loop frisch aus der Data Table gelesen ("Lese aktuellen
// Zustand") und gegen das erwartete Bugmuster geprueft ("Pruefe Bugmuster"), bevor
// irgendetwas geschrieben wird - ein zwischenzeitlich manuell oder automatisch
// veraenderter Datensatz wird NICHT ueberschrieben, siehe dortiger Kommentar.
//
// Bewusst NICHT dabei (siehe Memory allris_qa_block_race_2026-09-01 fuer die Begruendung
// je Fall): 2026/124 (unabhaengiger, spaeterer Paperless-Fehler), 2026/055 + 2026/024-01
// (bereits per Matrix -SKIP manuell abgehakt), 2026/241 (bereits korrekt+alarmiert),
// 2026/277 (keine verwertbare Fehlermeldung).
const TARGETS = [
  { vorgangKey: 'vol_10600', vorgangsnummer: '2026/109' },
  { vorgangKey: 'vol_10672', vorgangsnummer: '2026/152' },
  { vorgangKey: 'vol_10705', vorgangsnummer: '2026/178' },
  { vorgangKey: 'vol_10721', vorgangsnummer: '2026/191' },
  { vorgangKey: 'vol_10369', vorgangsnummer: '2025/467' }
];

if (!TARGETS.length) {
  throw new Error('[QABlockRestore] TARGETS im Node "Konfiguriere Ziele" befuellen.');
}

return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    restoreVisualDecisionReason: 'Wiederhergestellt (Einmalig-Reparatur 2026-09-01): urspruengliche QA-Block-Meldung wurde durch einen Fehler in "Repariere Legacy Visual-Status" faelschlich als "kein Sharepic noetig" ueberschrieben. Der QA-Agent-Aufruf war fehlgeschlagen, keine echte inhaltliche Pruefung fand statt. Bitte manuell pruefen oder per Matrix -OK/-SKIP entscheiden.'
  }
}));

// P0.1-Absicherung (2026-09-01 Folgeauftrag): defensiver Re-Read + Guard. Nur reparieren,
// wenn das erwartete Bugmuster JETZT, unmittelbar vor dem Schreibvorgang, noch exakt
// vorliegt - ein zwischenzeitlich veraenderter Zustand wird NIE ueberschrieben.
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

const target = $('Loop Ziele (1 pro Durchlauf)').item.json;
const rows = $input.all();

let decision, reason, row = null;

if (rows.length === 0) {
  decision = 'NOT_FOUND';
  reason = 'Kein Datensatz mit diesem vorgangKey mehr in allris_vorgaenge gefunden.';
} else if (rows.length > 1) {
  decision = 'ERROR';
  reason = 'vorgangKey ist nicht eindeutig (' + rows.length + ' Treffer) - vorgangKey sollte Primaerschluessel-artig eindeutig sein, abgebrochen zur Sicherheit.';
} else {
  row = rows[0].json || {};

  // Bugmuster-Kriterien, alle muessen weiterhin zutreffen:
  const contentErrorReasonOk = safeStr(row.contentErrorReason) === 'qa_blocked';
  const sharepicStageOk = safeStr(row.sharepicNeedStage) === 'not_applicable';

  // Keine zwischenzeitliche menschliche Entscheidung (z.B. "-SKIP"/"-OK" per Matrix,
  // erkennbar am Praefix "Manuell per Matrix", siehe P5b "Speichere Blockade-Antwort").
  const noHumanDecision = !safeStr(row.visualDecisionReason).startsWith('Manuell per Matrix');

  // Kein Hinweis, dass die Zeile bereits uebliche Freigabe/Benachrichtigung durchlaufen
  // hat, seit der Reparaturplanung entstanden (visualBlockNotifiedReason waere dann
  // gesetzt UND wuerde nicht mehr die alte, uninformative Notlage beschreiben).
  const notAlreadyNotified = !safeStr(row.visualBlockNotifiedReason);

  // Der Datensatz darf sich nicht bereits ein zweites Mal veraendert haben (z.B. durch
  // einen erneuten P3d-Lauf) - erkennbar daran, dass visualDecisionReason bereits unseren
  // eigenen Wiederherstellungstext traegt (waere ein Zeichen, dass dieses Tool schon
  // einmal fuer diese Zeile lief) oder bereits die "(Neuberechnung Legacy-Reparatur)"-
  // Markierung NICHT mehr traegt, obwohl contentErrorReason noch qa_blocked ist (waere
  // ein unbekannter, neuer Zustand, den wir nicht blind ueberschreiben wollen).
  const currentReason = safeStr(row.visualDecisionReason);
  const looksLikeKnownLegacyRepairText = currentReason.startsWith('Eignungs-Agent:') && currentReason.endsWith('(Neuberechnung Legacy-Reparatur)');
  const notAlreadyRestored = !currentReason.startsWith('Wiederhergestellt (Einmalig-Reparatur');

  const stillMatchesBugPattern = contentErrorReasonOk && sharepicStageOk && noHumanDecision && notAlreadyNotified && notAlreadyRestored && looksLikeKnownLegacyRepairText;

  if (stillMatchesBugPattern) {
    decision = 'UPDATE';
    reason = 'Bugmuster unveraendert vorhanden (contentErrorReason=qa_blocked, sharepicNeedStage=not_applicable, keine menschliche Zwischenentscheidung, keine vorherige Benachrichtigung, unveraenderter Legacy-Reparatur-Text).';
  } else {
    decision = 'SKIPPED_STATE_CHANGED';
    const details = [];
    if (!contentErrorReasonOk) details.push('contentErrorReason ist jetzt "' + safeStr(row.contentErrorReason) + '" statt "qa_blocked"');
    if (!sharepicStageOk) details.push('sharepicNeedStage ist jetzt "' + safeStr(row.sharepicNeedStage) + '" statt "not_applicable"');
    if (!noHumanDecision) details.push('visualDecisionReason zeigt bereits eine manuelle Matrix-Entscheidung: "' + currentReason.slice(0, 120) + '"');
    if (!notAlreadyNotified) details.push('visualBlockNotifiedReason ist bereits gesetzt: "' + safeStr(row.visualBlockNotifiedReason).slice(0, 120) + '"');
    if (!notAlreadyRestored) details.push('Zeile traegt bereits den Wiederherstellungstext dieses Tools (evtl. schon einmal gelaufen)');
    if (contentErrorReasonOk && sharepicStageOk && !looksLikeKnownLegacyRepairText) details.push('visualDecisionReason entspricht nicht mehr exakt dem erwarteten Legacy-Reparatur-Text: "' + currentReason.slice(0, 120) + '"');
    reason = details.join(' | ') || 'Zustand entspricht nicht mehr exakt dem erwarteten Bugmuster.';
  }
}

return [{
  json: {
    ...target,
    _decision: decision,
    _reason: reason,
    _currentSharepicNeedStage: row ? safeStr(row.sharepicNeedStage) : null,
    _currentVisualDecisionReason: row ? safeStr(row.visualDecisionReason) : null,
    _currentVisualBlockNotifiedReason: row ? safeStr(row.visualBlockNotifiedReason) : null,
    _lastErrorAt: row ? safeStr(row.last_error_at) : null
  }
}];

// CAS-Schutz: der Update-Filter enthaelt vorgangKey UND contentErrorReason='qa_blocked'
// UND sharepicNeedStage='not_applicable' als Bedingung. Hat sich der Datensatz im schmalen
// Fenster zwischen "Pruefe Bugmuster" und diesem Schreibvorgang nochmal veraendert, matcht
// der Filter keine Zeile mehr - der Data-Table-Node liefert dann 0 Items zurueck statt 1.
const target = $('Pruefe Bugmuster').item.json;
const updated = $input.all();

if (updated.length === 1) {
  return [{ json: { vorgangsnummer: target.vorgangsnummer, vorgangKey: target.vorgangKey, _decision: 'UPDATED', _reason: target._reason } }];
}
if (updated.length === 0) {
  return [{ json: { vorgangsnummer: target.vorgangsnummer, vorgangKey: target.vorgangKey, _decision: 'SKIPPED_STATE_CHANGED', _reason: 'CAS-Update traf 0 Zeilen - Zustand aenderte sich zwischen Pruefung und Schreibvorgang.' } }];
}
return [{ json: { vorgangsnummer: target.vorgangsnummer, vorgangKey: target.vorgangKey, _decision: 'ERROR', _reason: 'CAS-Update traf ' + updated.length + ' Zeilen statt 0 oder 1 - unerwartet, vorgangKey sollte eindeutig sein.' } }];

// Kompakte Ergebnisliste, gruppiert nach Status (UPDATED / SKIPPED_STATE_CHANGED /
// NOT_FOUND / ERROR) - siehe P0.1-Auftrag vom 2026-09-01 Folgeauftrag.
const items = $input.all().map(i => i.json);
const byStatus = {};
for (const it of items) {
  const key = it._decision || 'UNKNOWN';
  if (!byStatus[key]) byStatus[key] = [];
  byStatus[key].push({ vorgangsnummer: it.vorgangsnummer, vorgangKey: it.vorgangKey, grund: it._reason });
}

const summary = Object.keys(byStatus).map(k => k + ': ' + byStatus[k].length).join(', ');
console.log('[QABlockRestore] Ergebnis: ' + summary);
for (const [status, rows] of Object.entries(byStatus)) {
  for (const r of rows) {
    console.log('  ' + status + ' - ' + r.vorgangsnummer + ' (' + r.vorgangKey + '): ' + r.grund);
  }
}

return [{ json: { summary, byStatus, totalProcessed: items.length } }];
